    let searchTimer; $("#productSearch").oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=$("#productSearch").value.trim();if(q){try{const params=new URLSearchParams();if(state.warehouseId)params.set('warehouse_id',state.warehouseId);const found=await api(`/barcode/${encodeURIComponent(q)}?${params}`);if(found){if(!state.products.some(row=>row.id===found.id))state.products.push(found);addCartProduct(found.id,found.selected_unit_id);$("#productSearch").value='';return;}}catch(e){}}await loadProducts(q,$('.food-chip.active')?.dataset.category||'');renderCashierProducts();},300);};
    $("#saleCustomer").innerHTML='<option value="">زبون نقدي</option>'+state.customers.filter(c=>c.phone!=='FOOD-WALK-IN').map(c=>`<option value="${c.id}">${esc(c.name)} · دين ${money(c.debt)}</option>`).join('');
