    $("#clearCart").onclick=()=>{state.cart=[];renderCart();};
    $("#salePayment").onchange=()=>$("#salePaid").hidden=$("#salePayment").value==='cash'; $("#salePayment").dispatchEvent(new Event('change'));
    $("#completeSale").onclick=async()=>{if(!state.cart.length)return notice('السلة فارغة',true);try{const result=await api('/sales',{method:'POST',body:JSON.stringify({customer_id:$("#saleCustomer").value||null,warehouse_id:state.warehouseId,payment_type:$("#salePayment").value,paid_amount:$("#salePaid").value,items:state.cart.map(line=>({variant_id:line.variant.id,unit_id:line.unitId,warehouse_id:state.warehouseId,sale_mode:line.saleMode,quantity:line.quantity,discount:line.discount}))})});notice(`تم حفظ الفاتورة ${result.invoice_no} — ${money(result.total)}`);state.cart=[];renderCart();await loadProducts();renderCashierProducts();}catch(e){notice(e.message,true);}};
