    units.forEach(unit=>{const parent=$('[data-unit="parent"]',unit);if(!parent)return;const current=parent.value;parent.innerHTML=units.filter(other=>other!==unit).map(other=>`<option value="${other.dataset.unitKey}" ${other.dataset.unitKey===current?'selected':''}>${esc(unitLabel(other))}</option>`).join('');if(!parent.value&&base&&base!==unit)parent.value=base.dataset.unitKey;});
