  function addBarcodeRow(unit,data={}){const row=document.createElement('div');row.className='food-barcode-row';row.dataset.barcodeId=data.id||'';row.innerHTML=`<input data-barcode-value inputmode="numeric" autocomplete="off" value="${esc(data.value||'')}" placeholder="امسح أو اكتب الباركود"><label title="الباركود الرئيسي"><input data-barcode-primary type="radio" name="primary-${unit.dataset.unitKey}" ${data.is_primary?'checked':''}> رئيسي</label><span data-barcode-status></span><button type="button" class="food-remove" aria-label="حذف الباركود"><i class="fa fa-times"></i></button>`;const input=$('[data-barcode-value]',row);input.oninput=()=>{markProductDirty();clearTimeout(barcodeTimer);barcodeTimer=setTimeout(()=>validateBarcodeRow(row),350);};input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();validateBarcodeRow(row);addBarcodeRow(unit);$$('[data-barcode-value]',unit).at(-1)?.focus();}};row.querySelector('.food-remove').onclick=()=>{row.remove();if(!$$('.food-barcode-row',unit).length)addBarcodeRow(unit,{is_primary:true});markProductDirty();};$('[data-barcodes]',unit).appendChild(row);return row;}
  async function validateBarcodeRow(row){const input=$('[data-barcode-value]',row),status=$('[data-barcode-status]',row),value=input.value.trim();if(!value){status.textContent='';row.classList.remove('valid','invalid');return true;}try{const params=new URLSearchParams({value});if(row.dataset.barcodeId)params.set('exclude_id',row.dataset.barcodeId);const result=await api(`/barcodes/check?${params}`);status.textContent=result.message;row.classList.toggle('valid',result.available);row.classList.toggle('invalid',!result.available);return result.available;}catch(error){status.textContent=error.message;row.classList.add('invalid');return false;}}
  function addOpeningRow(variant,data={}){const row=document.createElement('div');row.className='food-opening-row';row.innerHTML=`<select data-opening="warehouse">${warehouseOptions(data.warehouse_id)}</select><select data-opening="unit"></select><input data-opening="quantity" type="number" min="0" value="${data.quantity||0}" placeholder="الكمية"><input data-opening="cost" type="number" min="0" value="${data.unit_cost||0}" placeholder="التكلفة"><input data-opening="batch" value="${esc(data.batch_number||'')}" placeholder="Batch / Lot"><input data-opening="production" type="date" value="${esc(data.production_date||'')}" title="تاريخ الإنتاج"><input data-opening="expiry" type="date" value="${esc(data.expiry_date||'')}" title="تاريخ الانتهاء"><button type="button" class="food-remove"><i class="fa fa-trash"></i></button>`;row.querySelector('.food-remove').onclick=()=>{row.remove();markProductDirty();};$$('input,select',row).forEach(control=>control.onchange=markProductDirty);$('[data-opening-stock]',variant).appendChild(row);refreshVariantUnitSelectors(variant);updateConditionalSections();return row;}
