  function renderInventory(tab='current'){const data=state.inventory;if(!data)return;const movementNames={opening:'رصيد افتتاحي',purchase:'شراء',sale:'بيع',sale_restore:'مرتجع/إلغاء بيع',purchase_reverse:'إلغاء شراء',inventory_count:'جرد'},expiryNames={expired:'منتهي',today:'ينتهي اليوم',within_7:'خلال 7 أيام',within_30:'خلال 30 يوماً',healthy:'سليم'};let html='';if(tab==='current')html=table(['المنتج','النوع','التصنيف','المخزون الأساسي','صيغة التعبئة','التكلفة','الحد الأدنى'],data.products.map(p=>`<tr><td>${esc(p.product_name)}</td><td>${esc(p.variant_name)}</td><td>${esc(p.category||'—')}</td><td>${p.track_stock?p.stock_base:'غير متتبّع'}</td><td>${p.track_stock?esc(p.stock_display):'—'}</td><td>${p.track_stock?money(p.stock_base*p.average_cost):'—'}</td><td>${p.track_stock?p.minimum_stock:'—'}</td></tr>`));if(tab==='movements')html=table(['التاريخ','المنتج','المخزن','الحركة','الكمية','قبل','بعد','المرجع','الموظف'],data.movements.map(m=>`<tr><td>${window.FinoraTime.dateTime(m.created_at)}</td><td>${esc(m.product)}<br><small>${esc(m.variant)}</small></td><td>${esc(m.warehouse||'المخزون العام')}</td><td><span class="food-badge">${esc(movementNames[m.type]||m.type)}</span></td><td>${m.quantity_base}</td><td>${m.before}</td><td>${m.after}</td><td>${m.reference_id?`${esc(m.reference_type||'')} #${m.reference_id}`:esc(m.note||'—')}</td><td>${esc(m.employee||'—')}</td></tr>`));if(tab==='low')html=table(['المنتج','النوع','المتوفر','الحد'],data.low_stock.map(p=>`<tr><td>${esc(p.product_name)}</td><td>${esc(p.variant_name)}</td><td><span class="food-badge warn">${p.stock_base}</span></td><td>${p.minimum_stock}</td></tr>`));if(tab==='expiry')html=table(['المنتج','المخزن','الدفعة','الكمية','الإنتاج','الانتهاء','الحالة'],data.expiry.map(x=>`<tr><td>${esc(x.product)}<br><small>${esc(x.variant)}</small></td><td>${esc(x.warehouse||'المخزون العام')}</td><td>${esc(x.batch||'—')}</td><td>${x.quantity_base}</td><td>${x.production_date||'—'}</td><td>${x.expiry_date}</td><td><span class="food-badge ${x.status==='healthy'?'':'warn'}">${esc(expiryNames[x.status]||x.status)}</span></td></tr>`));if(tab==='count'){const tracked=data.products.filter(p=>p.track_stock);const categories=[...new Set(tracked.map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'));html=`<div class="food-count-head"><p>أدخل الكمية الفعلية بالوحدة الأساسية. عند زيادة مادة تتبع الصلاحية يجب تحديد صلاحية للزيادة.</p><select id="countCategory"><option value="">كل التصنيفات</option>${categories.map(category=>`<option value="${esc(category)}">${esc(category)}</option>`).join('')}</select><input id="countNote" placeholder="ملاحظة الجرد" value="جرد يدوي"><button id="approveCount" class="food-primary">اعتماد الجرد</button></div>`+table(['المنتج','النوع','المسجل','الفعلي','الفرق','صلاحية الزيادة'],tracked.map(p=>`<tr data-count-row="${p.id}" data-count-category="${esc(p.category||'')}" data-recorded="${p.stock_base}"><td>${esc(p.product_name)}</td><td>${esc(p.variant_name)}</td><td>${p.stock_base}</td><td><input class="food-count-input" type="number" min="0" value="${p.stock_base}" data-count-value="${p.id}"></td><td data-count-diff="${p.id}">0</td><td>${p.track_expiry?`<input type="date" data-count-expiry="${p.id}">`:'—'}</td></tr>`));}$("#inventoryContent").innerHTML=html;if(tab==='count'){$("#countCategory").onchange=()=>{$$('[data-count-row]').forEach(row=>row.hidden=Boolean($("#countCategory").value)&&row.dataset.countCategory!==$("#countCategory").value);};$$('[data-count-value]').forEach(input=>input.oninput=()=>{const row=input.closest('[data-count-row]');const diff=Math.max(0,Number(input.value||0))-Number(row.dataset.recorded||0);$(`[data-count-diff="${input.dataset.countValue}"]`).textContent=diff>0?`+${diff}`:String(diff);});$("#approveCount").onclick=async()=>{const items=$$('[data-count-row]:not([hidden]) [data-count-value]').map(input=>({variant_id:Number(input.dataset.countValue),actual_base:Number(input.value),expiry_date:$(`[data-count-expiry="${input.dataset.countValue}"]`)?.value||null}));if(!confirm('اعتماد نتيجة الجرد وتسجيل فروقات المخزون؟'))return;try{const result=await api('/inventory/count',{method:'POST',body:JSON.stringify({note:$("#countNote").value,items})});notice(`تم اعتماد الجرد وتعديل ${result.changed} مادة`);state.inventory=await api('/inventory');renderInventory('count');}catch(e){notice(e.message,true);}};}}
