    $("#movementCount").textContent=Number(data.count||0).toLocaleString('en-IQ');
    $("#movementTotal").textContent=money(data.total);
    $("#movementLatest").textContent=data.rows.length?shortDate(data.rows[0].date):'لا توجد';
    $("#financeMovementsTable").innerHTML=table(['التاريخ','البيان / الطرف','رقم المستند','المبلغ','الملاحظة',''],data.rows.map((row,index)=>`<tr><td>${shortDate(row.date)}</td><td><b>${esc(row.party)}</b></td><td><span class="food-badge">${esc(row.reference)}</span></td><td><strong>${money(row.amount)}</strong></td><td>${esc(row.note||'—')}</td><td><button type="button" class="food-row-print" data-print-movement="${index}" title="طباعة السند"><i class="fa fa-print"></i><span>طباعة</span></button></td></tr>`));
    $$('[data-print-movement]').forEach(button=>button.onclick=()=>printFinanceMovement(data.rows[Number(button.dataset.printMovement)],data.section));
