  async function reloadFinanceRegister(section){renderFinanceRegister(await api(`/finance/movements/${section}`));}
  function setMovementModal(open){const modal=$("#movementModal");if(!modal)return;modal.hidden=!open;document.body.classList.toggle('food-modal-open',open);$("#toggleMovementForm")?.classList.toggle('active',open);if(open)setTimeout(()=>modal.querySelector('input:not([type="hidden"]),textarea')?.focus(),60);}
  function setupPartyPicker({items,searchId,resultsId,valueId,selectedId,label}){
    const search=$(searchId),results=$(resultsId),value=$(valueId),selected=$(selectedId);if(!search)return;
    const render=(query='')=>{const needle=query.trim().toLowerCase(),matches=items.filter(item=>!needle||`${item.name||''} ${item.phone||''}`.toLowerCase().includes(needle)).slice(0,8);results.innerHTML=matches.length?matches.map(item=>`<button type="button" data-party-id="${item.id}"><span><b>${esc(item.name)}</b><small>${esc(item.phone||'بدون رقم هاتف')}</small></span><strong>${money(item.debt)}</strong></button>`).join(''):`<div class="food-party-empty">لا توجد نتائج مطابقة</div>`;results.hidden=false;$$('[data-party-id]',results).forEach(button=>button.onclick=()=>{const item=items.find(row=>String(row.id)===button.dataset.partyId);value.value=item.id;search.value=item.name;selected.hidden=false;selected.innerHTML=`<i class="fa fa-circle-check"></i><span><small>${label} المحدد</small><b>${esc(item.name)}</b></span><strong>الذمة ${money(item.debt)}</strong>`;results.hidden=true;});};
    search.onfocus=()=>render(search.value);search.oninput=()=>{value.value='';selected.hidden=true;render(search.value);};search.onkeydown=event=>{if(event.key==='Escape')results.hidden=true;};document.addEventListener('click',event=>{if(!event.target.closest('.food-party-picker'))results.hidden=true;},{once:false});
  }
