      form.onsubmit=async event=>{event.preventDefault();if(!$("#paymentSupplier").value)return notice('اختر المورد من نتائج البحث',true);const submit=form.querySelector('button[type="submit"],button:not([type])');submit.disabled=true;try{const result=await api('/finance/supplier-payment',{method:'POST',body:JSON.stringify({supplier_id:$("#paymentSupplier").value,amount:$("#paymentAmount").value,document_number:$("#paymentDocumentNo").value,note:$("#paymentNote").value})});notice(`تم حفظ ${result.document_number} بمبلغ ${money(result.applied)}`);form.reset();$("#paymentSupplier").value='';$("#paymentPartySelected").hidden=true;setMovementModal(false);await loadParties();items=state.suppliers.filter(item=>Number(item.debt)>0);setupPartyPicker({items,searchId:'#paymentPartySearch',resultsId:'#paymentPartyResults',valueId:'#paymentSupplier',selectedId:'#paymentPartySelected',label:'المورد'});await reloadFinanceRegister(section);}catch(error){notice(error.message,true);}finally{submit.disabled=false;}};
